"use strict";(globalThis.webpackChunkpaper=globalThis.webpackChunkpaper||[]).push([[556],{4694:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/test","metadata":{"permalink":"/paper/news/test","source":"@site/news/test.md","title":"\ub274\uc2a4 \uc77d\uae30 \ud15c\ud50c\ub9bf","description":"\uae30\uc0ac \ud558\ub098\ub97c \uc77d\uace0 \uc694\uc57d, \uc758\ubbf8, \ub0b4 \uc0dd\uac01, \ub354 \ucc3e\uc544\ubcfc \uac83 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ud2c0.","date":"2026-11-02T00:00:00.000Z","tags":[],"readingTime":1.44,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\ub274\uc2a4 \uc77d\uae30 \ud15c\ud50c\ub9bf","description":"\uae30\uc0ac \ud558\ub098\ub97c \uc77d\uace0 \uc694\uc57d, \uc758\ubbf8, \ub0b4 \uc0dd\uac01, \ub354 \ucc3e\uc544\ubcfc \uac83 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ud2c0.","image":"https://picsum.photos/seed/paper-news/800/500","date":"2026-11-02T00:00:00.000Z"},"unlisted":false},"content":"\ub274\uc2a4\ub97c \uadf8\ub0e5 \uc77d\uace0 \ub118\uae30\uba74 \ud558\ub8e8\ub9cc \uc9c0\ub098\ub3c4 \uae30\uc5b5\uc5d0 \ub0a8\uc9c0 \uc54a\ub294\ub2e4. \uae30\uc0ac \ud558\ub098\ub97c \uace0\ub974\uace0, \uc544\ub798 \uc21c\uc11c\ub300\ub85c \uc9e7\uac8c\ub77c\ub3c4 \uc815\ub9ac\ud574 \ub450\uba74 \ub098\uc911\uc5d0 \ud750\ub984\uc744 \uc774\uc5b4\uc11c \ubcfc \uc218 \uc788\ub2e4. \uc774 \uae00\uc740 \uadf8 \uc815\ub9ac \ud2c0\uc744 \ud655\uc778\ud558\uae30 \uc704\ud55c \ud14c\uc2a4\ud2b8 \uae00\uc774\ub2e4.\\n\\n## \ud83d\udcf0 \ud5e4\ub4dc\ub77c\uc778\\n\\n- **\uae30\uc0ac \uc81c\ubaa9**: \uc5ec\uae30\uc5d0 \uae30\uc0ac \uc81c\ubaa9\uc744 \uc801\ub294\ub2e4\\n- **\ucd9c\ucc98 / \ub0a0\uc9dc**: \uc5b8\ub860\uc0ac, \ubc1c\ud589\uc77c\\n- **\ubd84\uc57c**: \uacbd\uc81c \xb7 \uae30\uc220 \xb7 \uc0ac\ud68c \xb7 \uad6d\uc81c \uc911 \ud558\ub098\\n\\n## \ud83e\uddfe \uc138 \uc904 \uc694\uc57d\\n\\n1. \ubb34\uc2a8 \uc77c\uc774 \uc788\uc5c8\ub098\\n2. \ub204\uac00, \uc65c \uadf8\ub807\uac8c \ud588\ub098\\n3. \uc55e\uc73c\ub85c \uc5b4\ub5bb\uac8c \ub420 \uac83\uc73c\ub85c \ubcf4\ub098\\n\\n## \ud83d\udca1 \uc65c \uc911\uc694\ud55c\uac00\\n\\n\uc774 \uc18c\uc2dd\uc774 \ub098\uc758 \uc77c, \ub0b4 \ub3c8, \ub0b4\uac00 \uad00\uc2ec \uc788\ub294 \ubd84\uc57c\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0 \ud55c\ub450 \ubb38\ub2e8\uc73c\ub85c \uc801\ub294\ub2e4. \uc22b\uc790\uac00 \ub098\uc628\ub2e4\uba74 \uadf8 \uc22b\uc790\uac00 \ud070 \uac74\uc9c0 \uc791\uc740 \uac74\uc9c0 \ube44\uad50 \ub300\uc0c1\uc744 \ud568\uaed8 \uc801\uc5b4 \ub450\uba74 \uc88b\ub2e4.\\n\\n## \ud83e\udd14 \ub0b4 \uc0dd\uac01\\n\\n> \uae30\uc0ac\uc758 \uc8fc\uc7a5\uacfc \ub0b4 \uc0dd\uac01\uc744 \uad6c\ubd84\ud574\uc11c \uc801\uae30.\\n\\n## \ud83d\udd0e \ub354 \ucc3e\uc544\ubcfc \uac83\\n\\n- [ ] \uad00\ub828 \uc6a9\uc5b4 \uc815\ub9ac\\n- [ ] \uac19\uc740 \uc8fc\uc81c\uc758 \ub2e4\ub978 \uc5b8\ub860\uc0ac \uae30\uc0ac \ube44\uad50\\n- [ ] \ud55c \ub2ec \ub4a4 \ud6c4\uc18d \ubcf4\ub3c4 \ud655\uc778"}]}}')}}]);